python
def magnitudeOrderThresholdFile(readings, k):
    a=readings
    out=[]
    out=sorted(a,key=lambda x:(abs(x),x))
    return sum(x>=k for x in out)


java
class Solution {
  public int magnitudeOrderThresholdFile(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {Integer[]copy=Arrays.stream(a).boxed().toArray(Integer[]::new);Arrays.sort(copy,Comparator.comparingInt((Integer x)->Math.abs(x)).thenComparingInt(x->x));out.addAll(Arrays.asList(copy));}
    int answer=0;for(int x:out)if(x>=k)answer++;return answer;
  }
}
